/* frontend/src/components/Profile.js */
import React, { useState, useEffect } from 'react';

export default function Profile() {
  // 1. Setup state to hold the dynamic user data
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // 2. This pulls the specific user who logged in from the browser's memory
    const storedUser = localStorage.getItem('user');

    if (storedUser) {
      setUser(JSON.parse(storedUser));
    }
    setLoading(false);
  }, []);

  // Show loading state while fetching from localStorage
  if (loading) return <div className="loading-screen">Loading Profile...</div>;

  // If no user is found, redirect or show error
  if (!user) return <div className="error-screen">Please log in to view your profile.</div>;

  // 3. Dynamic Calculation for the Progress Bar
  const progressPercent = user.nextXp > 0 ? (user.xp / user.nextXp) * 100 : 0;

  return (
    <div className="profile-page-wrapper">
      {/* Dynamic Header Card - Matches Screenshot 14.32.11 */}
      <div className="profile-header-card">
        <div className="profile-banner-gradient"></div>
        <div className="profile-info-row">
          <div className="profile-avatar-large">
            {/* Dynamic Initial: Automatically takes first letter of the name */}
            <span className="avatar-icon">
              {user.fullName ? user.fullName.charAt(0).toUpperCase() : 'U'}
            </span>
          </div>
          <div className="profile-user-details">
            {/* DYNAMIC NAME & EMAIL */}
            <h1>{user.fullName || "User Name"}</h1>
            <p>VidyaQuest Learner • {user.email || "user@email.com"}</p>
          </div>
          <div className="profile-actions">
            <button className="edit-btn">✏️ Edit Profile</button>
            <button 
              className="signout-btn" 
              onClick={() => { localStorage.clear(); window.location.href = '/login'; }}
            >
              📤 Sign Out
            </button>
          </div>
        </div>
      </div>

      <div className="profile-stats-grid">
        {/* Dynamic Level Progress Section */}
        <div className="profile-section-card">
          <div className="section-header">
            <span className="section-icon green">🏆</span>
            <h3>Level Progress</h3>
          </div>
          <div className="level-card-content">
             <div className="level-badge">{user.level || 1}</div>
             <div className="level-details">
                <div className="level-text">
                  Level {user.level || 1} <span>{user.xp || 0} / {user.nextXp || 500} XP</span>
                </div>
                <div className="progress-bar-container">
                  {/* The Orange Bar width changes based on user.xp */}
                  <div 
                    className="progress-fill" 
                    style={{ width: `${progressPercent}%` }}
                  ></div>
                </div>
                <p>{(user.nextXp || 500) - (user.xp || 0)} XP until Level {(user.level || 1) + 1}</p>
             </div>
          </div>
        </div>

        {/* Badges Section */}
        <div className="profile-section-card">
          <div className="section-header">
            <span className="section-icon green">🏅</span>
            <h3>Badges</h3>
          </div>
          <div className="badges-empty-state">
             <div className="empty-badge-icon">🎖️</div>
             <p>Complete quizzes to earn badges!</p>
          </div>
        </div>
      </div>
    </div>
  );
}
